@import "tailwindcss/theme.css" layer(theme);
@import "tailwindcss/preflight.css" layer(base);

@theme {
  --color-rd-ink: #272B32;
  --color-rd-paper: #F3F0E8;
  --color-rd-orange: #F26836;
  --color-rd-blue: #244BA8;
  --color-rd-mint: #B8E9DD;
}

:root {
  --rd-ink: #272B32;
  --rd-paper: #F3F0E8;
  --rd-orange: #F26836;
  --rd-blue: #244BA8;
  --rd-mint: #B8E9DD;
  --rd-display: var(--font-rd-exo), sans-serif;
  --rd-body-font: var(--font-rd-space), sans-serif;
  --rd-mono: var(--font-rd-plex), monospace;
  --rd-ease: cubic-bezier(.16, 1, .3, 1);
  --rd-ease-io: cubic-bezier(.77, 0, .175, 1);
  --rd-spring: linear(0, .35 8%, .82 20%, 1.06 30%, 1.02 42%, .99 58%, 1);
  --rd-instant: 90ms;
  --rd-fast: 180ms;
  --rd-base: 420ms;
  --rd-slow: 800ms;
  --rd-hero-duration: 1200ms;
  --rd-progress: 0;
  --rd-unfold: 0;
  --rd-unfold-top: 62%;
  --rd-unfold-bottom: 18%;
  --rd-mobile-cut-top: 27%;
  --rd-mobile-cut-bottom: 78%;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
.rd-body { margin: 0; background: var(--rd-paper); color: var(--rd-ink); font-family: var(--rd-body-font); overflow-x: clip; }
.rd-body button, .rd-body input, .rd-body textarea, .rd-body select { font: inherit; }
.rd-body button, .rd-body a, .rd-body summary { -webkit-tap-highlight-color: transparent; }
.rd-body a { color: inherit; }
.rd-body img, .rd-body svg { display: block; }
.rd-body :focus-visible { outline: 3px solid var(--rd-orange); outline-offset: 4px; }
.rd-body main { display: block; }
.rd-skip { position: fixed; left: 12px; top: 12px; z-index: 200; padding: 12px; background: var(--rd-ink); color: var(--rd-paper) !important; transform: translateY(-160%); }
.rd-skip:focus { transform: none; }
.rd-placeholder { display: grid; place-items: center; background: color-mix(in srgb, var(--rd-ink) 12%, var(--rd-paper)); font: 500 11px/1.4 var(--rd-mono); min-height: 180px; }

.rd-header { height: 76px; padding: 0 clamp(22px, 4.2vw, 72px); display: flex; align-items: center; gap: 34px; position: sticky; top: 0; z-index: 80; background: var(--rd-paper); border-bottom: 1px solid color-mix(in srgb, var(--rd-ink) 20%, transparent); transition: background-color var(--rd-fast) var(--rd-ease); }
html[data-rd-scrolled="true"] .rd-header { background: color-mix(in srgb, var(--rd-paper) 96%, transparent); }
.rd-home { flex: 0 0 auto; width: 150px; transform-origin: left center; transition: transform var(--rd-base) var(--rd-ease); }
html[data-rd-scrolled="true"] .rd-home { transform: scale(.94); }
.rd-home svg { width: 100%; height: auto; }
.rd-desktop-nav { display: flex; align-items: center; gap: clamp(18px, 2.4vw, 40px); margin: 0 auto; }
.rd-desktop-nav a, .rd-header-cta { position: relative; text-decoration: none; text-transform: uppercase; font: 600 10px/1 var(--rd-mono); letter-spacing: .045em; white-space: nowrap; }
.rd-desktop-nav a::after { content: ""; position: absolute; left: 0; right: 0; bottom: -9px; height: 3px; background: var(--rd-orange); transform: scaleX(0); transform-origin: left; transition: transform var(--rd-base) var(--rd-ease); }
.rd-desktop-nav a:hover::after, .rd-desktop-nav a:focus-visible::after { transform: scaleX(1); }
.rd-header-cta { display: flex; align-items: center; gap: 22px; border: 1px solid var(--rd-ink); padding: 13px 15px; transition: background var(--rd-fast), transform var(--rd-fast) var(--rd-spring); }
.rd-header-cta:hover, .rd-header-cta:focus-visible { background: var(--rd-mint); }
.rd-header-cta:active { transform: scale(.97); }
.rd-mobile-menu { display: none; }
.rd-progress { position: absolute; bottom: -1px; left: 0; right: 0; height: 2px; pointer-events: none; }
.rd-progress span { display: block; height: 100%; width: 100%; transform: scaleX(var(--rd-progress)); transform-origin: left; background: var(--rd-orange); }

.rd-hero { position: relative; height: min(900px, calc(100svh - 76px)); min-height: 650px; overflow: hidden; isolation: isolate; background: var(--rd-paper); }
.rd-hero-field { position: absolute; inset: 0; background: var(--rd-blue); clip-path: polygon(var(--rd-unfold-top) 0, 100% 0, 100% 100%, var(--rd-unfold-bottom) 100%); }
.rd-hero-orange { position: absolute; inset: 0; background: var(--rd-orange); opacity: calc(1 - var(--rd-unfold)); clip-path: polygon(96% 0, 100% 0, 100% 100%, 58% 100%); }
.rd-hero-ghost { position: absolute; z-index: 0; right: -2%; top: 13%; width: 76%; height: auto; fill: var(--rd-paper); opacity: .11; transform: translate3d(0, calc(var(--rd-unfold) * -28px), 0); }
.rd-hero-coordinate { position: absolute; left: clamp(15px, 2vw, 30px); top: 70px; writing-mode: vertical-rl; transform: rotate(180deg); font: 500 9px/1 var(--rd-mono); letter-spacing: .13em; }
.rd-hero-copy { position: relative; z-index: 4; padding: clamp(62px, 9vh, 100px) 0 85px clamp(70px, 7vw, 120px); width: min(47%, 620px); }
.rd-kicker { margin: 0; font: 600 10px/1.4 var(--rd-mono); letter-spacing: .08em; text-transform: uppercase; }
.rd-hero-kicker span { display: inline-block; width: 8px; height: 8px; margin-right: 8px; background: var(--rd-orange); }
.rd-hero h1 { margin: 31px 0 23px; font: italic 900 clamp(68px, 7vw, 112px)/.82 var(--rd-display); letter-spacing: -.062em; text-transform: uppercase; }
.rd-hero h1 span { display: block; white-space: nowrap; }
.rd-hero h1 i { color: var(--rd-orange); font-style: normal; }
.rd-hero-lead { max-width: 265px; font-size: 17px; line-height: 1.5; font-weight: 500; margin: 0 0 25px; }
.rd-hero-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 19px; }
.rd-button { position: relative; display: inline-flex; align-items: center; justify-content: space-between; gap: 44px; padding: 19px 21px; min-height: 54px; background: var(--rd-orange); color: var(--rd-ink); text-decoration: none; font-size: 13px; line-height: 1; font-weight: 700; overflow: hidden; isolation: isolate; transition: transform var(--rd-fast) var(--rd-spring); }
.rd-button::before { content: ""; position: absolute; inset: 0; z-index: -1; background: var(--rd-mint); transform: scaleX(0); transform-origin: left; transition: transform var(--rd-base) var(--rd-ease); }
.rd-button:hover::before, .rd-button:focus-visible::before { transform: scaleX(1); }
.rd-button b { font-size: 16px; transition: transform var(--rd-fast) var(--rd-ease); }
.rd-button:hover b { transform: translate(3px, -3px); }
.rd-button:active { transform: scale(.97); }
.rd-link { font-size: 13px; font-weight: 700; text-decoration: underline; text-underline-offset: 5px; text-decoration-thickness: 1px; }
.rd-link span { display: inline-block; transition: transform var(--rd-fast) var(--rd-ease); }
.rd-link:hover span { transform: translate(3px, -3px); }
.rd-hero-bike-wrap { position: absolute; z-index: 2; width: 69%; right: 0; bottom: 3%; transform: translate3d(0, calc(var(--rd-unfold) * -30px), 0); }
.rd-hero-bike { display: block; width: 100%; }
.rd-hero-bike img { width: 100%; height: auto; filter: drop-shadow(0 20px 15px color-mix(in srgb, var(--rd-ink) 25%, transparent)); }
.rd-hero-wheel-intro { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: var(--rd-paper); stroke-width: 5; opacity: 0; pointer-events: none; }
.rd-wheel-selector { position: absolute; z-index: 5; right: 4.5%; bottom: 14%; display: flex; width: clamp(100px, 9vw, 138px); aspect-ratio: 1; flex-direction: column; align-items: center; justify-content: center; gap: 5px; border: 1px solid var(--rd-paper); border-radius: 50%; color: var(--rd-paper) !important; text-align: center; text-decoration: none; font: 500 9px/1.1 var(--rd-mono); transition: background-color var(--rd-base) var(--rd-ease), transform var(--rd-base) var(--rd-ease); }
.rd-wheel-selector strong { font: 400 31px/1 var(--rd-body-font); }
.rd-wheel-selector small { font: 500 9px/1.1 var(--rd-mono); }
.rd-wheel-selector:hover, .rd-wheel-selector:focus-visible { background: var(--rd-paper); color: var(--rd-ink) !important; }
@media (hover: hover) and (pointer: fine) { .rd-wheel-selector:hover { transform: rotate(8deg); } }
.rd-wheel-selector:active { transform: scale(.96); transition-duration: var(--rd-instant); }
.rd-hero-bottom { position: absolute; z-index: 6; left: 0; right: 0; bottom: 0; display: flex; justify-content: space-between; background: var(--rd-ink); color: var(--rd-paper); padding: 13px clamp(20px, 4vw, 65px); font: 600 9px/1 var(--rd-mono); letter-spacing: .08em; }

.rd-breakdown { padding: 0 clamp(22px, 5vw, 80px) clamp(90px, 10vw, 160px); scroll-margin-top: 65px; }
.rd-section-top { display: flex; justify-content: space-between; gap: 20px; padding: 26px 0; border-bottom: 1px solid var(--rd-ink); font: 600 10px/1.3 var(--rd-mono); letter-spacing: .06em; }
.rd-breakdown-heading { display: grid; grid-template-columns: 1fr minmax(220px, 360px); align-items: end; gap: 40px; padding: clamp(72px, 9vw, 145px) 0 55px; }
.rd-breakdown-heading h2 { margin: 20px 0 0; font: italic 900 clamp(54px, 7.5vw, 112px)/.9 var(--rd-display); letter-spacing: -.06em; }
.rd-breakdown-heading h2 em { color: var(--rd-blue); font-style: inherit; }
.rd-breakdown-heading > p { max-width: 340px; font-size: 16px; line-height: 1.6; margin: 0; }
.rd-blueprint { position: relative; overflow: hidden; min-height: 420px; background: var(--rd-blue); color: var(--rd-paper); }
.rd-blueprint-grid { position: absolute; inset: 0; opacity: .18; background-image: linear-gradient(var(--rd-paper) 1px, transparent 1px), linear-gradient(90deg, var(--rd-paper) 1px, transparent 1px); background-size: 44px 44px; }
.rd-blueprint-tag, .rd-blueprint-bottom { position: absolute; z-index: 2; left: 24px; right: 24px; display: flex; justify-content: space-between; font: 600 10px/1 var(--rd-mono); letter-spacing: .06em; }
.rd-blueprint-tag { top: 24px; }.rd-blueprint-bottom { bottom: 24px; }
.rd-blueprint-bike { display: block; position: relative; z-index: 1; width: min(78%, 1050px); margin: -2% auto; }
.rd-blueprint-bike img { width: 100%; height: auto; }
.rd-detail-strips { display: grid; grid-template-columns: repeat(3, 1fr); border-bottom: 1px solid var(--rd-ink); }
.rd-detail-strips > * { position: relative; min-height: 155px; padding: 25px 24px; border-right: 1px solid var(--rd-ink); text-decoration: none; }
.rd-detail-strips > :first-child { border-left: 1px solid var(--rd-ink); }
.rd-detail-strips span, .rd-angle-note span { font: 600 10px/1 var(--rd-mono); letter-spacing: .05em; }
.rd-detail-strips p { margin: 20px 0 0; font-size: 15px; line-height: 1.4; }
.rd-detail-strips b { position: absolute; right: 24px; bottom: 24px; font-size: 20px; transition: transform var(--rd-base) var(--rd-ease); }
.rd-detail-strips a:hover b { transform: translate(5px, -5px); }
.rd-detail-strips a:hover { background: var(--rd-mint); }
.rd-angle-note { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr); margin-top: clamp(80px, 10vw, 150px); background: var(--rd-ink); color: var(--rd-paper); }
.rd-angle-photo { display: block; min-width: 0; width: 100%; min-height: 360px; overflow: hidden; }
.rd-angle-photo img { width: 100%; height: 100%; object-fit: cover; }
.rd-angle-note > div { display: flex; flex-direction: column; align-items: flex-start; justify-content: space-between; gap: 50px; padding: clamp(28px, 4vw, 62px); }
.rd-angle-note p { margin: 0; font: italic 800 clamp(34px, 3.5vw, 56px)/.95 var(--rd-display); letter-spacing: -.04em; }
.rd-angle-note p em { color: var(--rd-mint); font-style: inherit; }
.rd-angle-note a { font-size: 13px; font-weight: 700; text-underline-offset: 5px; }

@media (prefers-reduced-motion: no-preference) {
  [data-reveal] { transition: opacity var(--rd-slow) var(--rd-ease), transform var(--rd-slow) var(--rd-ease), clip-path var(--rd-slow) var(--rd-ease-io); }
  .rd-js [data-reveal="rise"]:not([data-in="true"]) { opacity: 0; transform: translateY(28px); }
  /* A narrow edge stays in the intersection box so the observer can start the wipe. */
  .rd-js [data-reveal="wipe"]:not([data-in="true"]) { clip-path: inset(0 98% 0 0); }
  .rd-js [data-reveal="draw"]:not([data-in="true"]) { transform: scaleX(.02); transform-origin: left; }
  .rd-js [data-reveal="scale"]:not([data-in="true"]) { opacity: 0; transform: scale(.96); }
  .rd-hero-field { animation: rd-field-in var(--rd-hero-duration) var(--rd-ease) backwards; }
  html[data-rd-has-scrolled="true"] .rd-hero-field { animation: none; }
  .rd-hero-copy { animation: rd-copy-in var(--rd-base) var(--rd-ease) 60ms backwards; }
  .rd-hero h1 span { animation: rd-line-in var(--rd-base) var(--rd-ease) backwards; }
  .rd-hero h1 span:nth-child(1) { animation-delay: 120ms; }
  .rd-hero h1 span:nth-child(2) { animation-delay: 170ms; }
  .rd-hero h1 span:nth-child(3) { animation-delay: 220ms; }
  .rd-hero-bike-wrap { animation: rd-bike-in var(--rd-hero-duration) var(--rd-ease) 100ms backwards; }
  .rd-hero-wheel-intro { animation: rd-wheel-fade 900ms var(--rd-ease) 250ms backwards; }
  .rd-hero-wheel-intro > g > g { animation: rd-wheel-turn 900ms var(--rd-ease) 250ms backwards; }
  .rd-wheel-selector { animation: rd-selector-in var(--rd-slow) var(--rd-ease) 600ms backwards; }
  @keyframes rd-field-in { from { clip-path: polygon(100% 0,100% 0,100% 100%,100% 100%); } to { clip-path: polygon(62% 0,100% 0,100% 100%,18% 100%); } }
  @keyframes rd-copy-in { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes rd-line-in { from { clip-path: inset(0 0 100% 0); transform: translateY(24px); } to { clip-path: inset(0); transform: translateY(0); } }
  @keyframes rd-bike-in { from { opacity: 0; clip-path: polygon(100% 0,100% 0,100% 100%,100% 100%); } to { opacity: 1; clip-path: polygon(0 0,100% 0,100% 100%,0 100%); } }
  @keyframes rd-wheel-fade { 0% { opacity: 0; } 25% { opacity: .42; } 100% { opacity: 0; } }
  @keyframes rd-wheel-turn { from { transform: rotate(-8deg); } to { transform: rotate(0); } }
  @keyframes rd-selector-in { from { opacity: 0; transform: rotate(-18deg) scale(.85); } to { opacity: 1; transform: rotate(0) scale(1); } }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .rd-body *, .rd-body *::before, .rd-body *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
  .rd-hero-ghost, .rd-hero-bike-wrap, .rd-wheel-selector:hover, .rd-wheel-selector:focus-visible, .rd-wheel-selector:active, html[data-rd-scrolled="true"] .rd-home { transform: none; }
}
@media (max-width: 900px) {
  .rd-desktop-nav { gap: 18px; }
  .rd-desktop-nav a:last-child { display: none; }
  .rd-header { padding-inline: 24px; }
  .rd-home { width: 130px; }
  .rd-hero-copy { padding-left: 7%; }
  .rd-hero h1 { font-size: clamp(55px, 7vw, 75px); }
  .rd-hero-bike-wrap { width: 72%; }
}
@media (max-width: 700px) {
  .rd-header, html[data-rd-scrolled="true"] .rd-header { height: 64px; padding-inline: 20px; }
  .rd-home { width: 132px; }
  .rd-desktop-nav, .rd-header-cta { display: none; }
  .rd-mobile-menu { display: block; margin-left: auto; }
  .rd-mobile-menu summary { display: flex; flex-direction: column; justify-content: center; gap: 5px; width: 44px; height: 44px; padding: 9px; list-style: none; cursor: pointer; }
  .rd-mobile-menu summary::-webkit-details-marker { display: none; }
  .rd-mobile-menu summary span { display: block; width: 25px; height: 2px; background: var(--rd-ink); transition: transform var(--rd-base) var(--rd-ease), opacity var(--rd-fast); }
  .rd-mobile-menu[open] summary span:first-child { transform: translateY(7px) rotate(45deg); }
  .rd-mobile-menu[open] summary span:nth-child(2) { opacity: 0; }
  .rd-mobile-menu[open] summary span:last-child { transform: translateY(-7px) rotate(-45deg); }
  .rd-mobile-menu nav { position: absolute; top: 100%; left: 0; right: 0; padding: 15px 22px 30px; background: var(--rd-ink); color: var(--rd-paper); }
  .rd-mobile-menu nav a { display: flex; justify-content: space-between; align-items: center; padding: 18px 0; border-bottom: 1px solid color-mix(in srgb, var(--rd-paper) 30%, transparent); text-decoration: none; font: italic 800 25px/1 var(--rd-display); text-transform: uppercase; }
  .rd-mobile-menu nav a span { font: 500 10px/1 var(--rd-mono); }
  .rd-hero { height: 760px; min-height: 0; }
  .rd-hero-field { clip-path: polygon(100% var(--rd-mobile-cut-top),100% 100%,0 100%,0 var(--rd-mobile-cut-bottom)); }
  .rd-hero-orange { clip-path: polygon(100% 30%,100% 100%,57% 100%); }
  .rd-hero-copy { width: 100%; padding: 46px 24px 0; }
  .rd-hero h1 { font-size: clamp(56px, 14vw, 88px); margin: 25px 0 22px; }
  .rd-hero-lead { font-size: 16px; max-width: 260px; margin-bottom: 20px; }
  .rd-hero-actions { gap: 16px; }
  .rd-hero-coordinate { display: none; }
  .rd-hero-ghost { top: 50%; right: -5%; width: 100%; }
  .rd-hero-bike-wrap { width: 100%; right: 0; bottom: 4%; }
  .rd-wheel-selector { width: 82px; right: 5%; bottom: 8%; font-size: 8px; }
  .rd-wheel-selector strong { font-size: 24px; }.rd-wheel-selector small { display: none; }
  .rd-hero-bottom { padding: 12px 20px; font-size: 8px; }
  .rd-breakdown { padding-inline: 20px; }
  .rd-section-top { font-size: 9px; }
  .rd-section-top span:last-child { text-align: right; }
  .rd-breakdown-heading { grid-template-columns: 1fr; gap: 26px; padding: 75px 0 34px; }
  .rd-breakdown-heading h2 { font-size: clamp(48px, 12vw, 76px); }
  .rd-blueprint { min-height: 270px; display: grid; align-items: center; }
  .rd-blueprint-bike { width: 100%; margin: 0; }
  .rd-blueprint-tag, .rd-blueprint-bottom { left: 14px; right: 14px; font-size: 8px; }
  .rd-detail-strips { grid-template-columns: 1fr; }
  .rd-detail-strips > * { min-height: 110px; border-left: 1px solid var(--rd-ink); border-bottom: 1px solid var(--rd-ink); }
  .rd-detail-strips > :last-child { border-bottom: 0; }
  .rd-angle-note { grid-template-columns: minmax(0, 1fr); }
  .rd-angle-photo { min-height: 0; aspect-ratio: 16 / 9; }
  .rd-angle-note > div { min-height: 280px; }
  @keyframes rd-field-in { from { clip-path: polygon(100% 100%,100% 100%,0 100%,0 100%); } to { clip-path: polygon(100% 27%,100% 100%,0 100%,0 78%); } }
}
@media (max-width: 360px) {
  .rd-hero { height: 720px; }
  .rd-hero h1 { font-size: 48px; }
  .rd-hero-copy { padding-top: 37px; }
}

/* RADIUS multi-page extensions — preserves sharp 0px Swiss technical geometry and five registered --rd-* tokens. */

.rd-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.rd-sub-hero {
  position: relative;
  overflow: hidden;
  padding: clamp(32px, 4.5vw, 56px) clamp(22px, 5vw, 80px) clamp(44px, 6vw, 80px);
  border-bottom: 1px solid var(--rd-ink);
  background: var(--rd-paper);
}

.rd-sub-hero--blue {
  background: var(--rd-blue);
  color: var(--rd-paper);
}

.rd-sub-hero--ink {
  background: var(--rd-ink);
  color: var(--rd-paper);
}

.rd-sub-shell {
  max-width: 1280px;
  margin-inline: auto;
}

.rd-crumb {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  font: 600 10px/1 var(--rd-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  opacity: 0.82;
}
.rd-crumb:hover { opacity: 1; text-decoration: underline; text-underline-offset: 4px; }

.rd-sub-hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(240px, 0.65fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: end;
}

.rd-sub-hero__title {
  margin: 18px 0 0;
  font: italic 900 clamp(46px, 6.4vw, 96px) / 0.88 var(--rd-display);
  letter-spacing: -0.055em;
  text-transform: uppercase;
}

.rd-sub-hero__title em {
  color: var(--rd-orange);
  font-style: inherit;
}

.rd-sub-hero--blue .rd-sub-hero__title em {
  color: var(--rd-mint);
}

.rd-sub-hero__lede {
  margin: 20px 0 0;
  max-width: 54ch;
  font-size: clamp(16px, 1.15vw, 19px);
  line-height: 1.55;
}

.rd-spec-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid currentColor;
  border-left: 1px solid currentColor;
}

.rd-spec-strip > div {
  padding: 14px 16px;
  border-right: 1px solid currentColor;
  border-bottom: 1px solid currentColor;
  display: grid;
  gap: 6px;
}

.rd-spec-strip span {
  font: 500 9.5px/1 var(--rd-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.78;
}

.rd-spec-strip strong {
  font: italic 800 20px/1.05 var(--rd-display);
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.rd-sub-section {
  padding: clamp(56px, 7vw, 108px) clamp(22px, 5vw, 80px);
  border-bottom: 1px solid color-mix(in srgb, var(--rd-ink) 18%, transparent);
}

.rd-sub-section--blue {
  background: var(--rd-blue);
  color: var(--rd-paper);
}

.rd-sub-section--ink {
  background: var(--rd-ink);
  color: var(--rd-paper);
}

